+function makeEnemy(pos,index){const g=new THREE.Group();g.position.set(pos[0],0,pos[1]);scene.add(g);const torso=new THREE.Mesh(new THREE.CapsuleGeometry(.37,.68,4,8),enemyMat);torso.position.y=1.15;torso.castShadow=true;g.add(torso);const vest=new THREE.Mesh(new THREE.BoxGeometry(.61,.47,.35),armorMat);vest.position.set(0,1.26,.04);vest.castShadow=true;g.add(vest);const head=new THREE.Mesh(new THREE.SphereGeometry(.245,12,10),skinMat);head.position.y=1.88;head.castShadow=true;g.add(head);const helmet=new THREE.Mesh(new THREE.SphereGeometry(.27,12,8,0,Math.PI*2,0,Math.PI*.56),mats.dark);helmet.position.y=1.99;helmet.castShadow=true;g.add(helmet);for(const s of [-1,1]){const limb=new THREE.Mesh(new THREE.CapsuleGeometry(.115,.55,3,6),armorMat);limb.position.set(s*.48,1.18,.05);limb.rotation.z=s*.2;limb.castShadow=true;g.add(limb);const leg=new THREE.Mesh(new THREE.CapsuleGeometry(.14,.55,3,6),mats.dark);leg.position.set(s*.19,.45,0);leg.castShadow=true;g.add(leg)}const gun=box(.16,.13,.8,0,0,0,mats.metal,false);gun.position.set(0,1.12,-.42);g.add(gun);const hp=new THREE.Group();hp.position.y=2.3;g.add(hp);const bg=new THREE.Mesh(new THREE.PlaneGeometry(.9,.08),new THREE.MeshBasicMaterial({color:0x17211e,side:THREE.DoubleSide}));hp.add(bg);const fill=new THREE.Mesh(new THREE.PlaneGeometry(.86,.045),new THREE.MeshBasicMaterial({color:0xd8f36a,side:THREE.DoubleSide}));fill.position.z=.006;hp.add(fill);enemies.push({g,hp,fill,health:100,alive:true,cooldown:1.5+Math.random()*2,walk:Math.random()*4,index});}
