+const $=s=>document.querySelector(s);function updateHUD(){$('#health').innerHTML=Math.ceil(health)+'<span>%</span>';$('#armor').innerHTML=Math.ceil(armor)+'<span>%</span>';$('#healthbar').style.width=Math.max(0,health)+'%';$('#ammo').textContent=ammo;$('#reserve').textContent=reserve;$('#progress').style.width=(kills/5*100)+'%';$('#timer').textContent=`${String(Math.floor(time/60)).padStart(2,'0')}:${String(Math.max(0,Math.ceil(time%60))).padStart(2,'0')}`;$('#roundNo').textContent=String(round).padStart(2,'0')}
+function showToast(t){const el=$('#toast');el.textContent=t;el.classList.add('on');toastTimer=1.5}
+function startGame(){if(!started){started=true;overlay.style.display='none';hud.style.display='block';if(matchMedia('(pointer:fine)').matches)renderer.domElement.requestPointerLock?.();showToast('HOSTILE CONTACTS — MOVE IN');clock.getDelta()}else if(paused){paused=false;overlay.style.display='none';hud.style.display='block';if(matchMedia('(pointer:fine)').matches)renderer.domElement.requestPointerLock?.();clock.getDelta()}}
+$('#play').addEventListener('click',startGame);
+document.addEventListener('pointerlockchange',()=>{if(started&&document.pointerLockElement!==renderer.domElement&&!matchMedia('(pointer:coarse)').matches&&!alive){return}if(started&&document.pointerLockElement!==renderer.domElement&&!matchMedia('(pointer:coarse)').matches&&alive){paused=true;overlay.style.display='grid';hud.style.display='none';document.querySelector('.eyebrow').textContent='SIMULATION PAUSED';document.querySelector('h1').innerHTML='Counter<span>Striker</span>';document.querySelector('.intro p').textContent='Take a breath. Your squad is waiting.';document.querySelector('.rules').style.display='none';$('#play').innerHTML='RESUME <span>↗</span>'}});
