+renderer.domElement.addEventListener('mousedown',e=>{if(e.button===0){if(!started)startGame();else if(document.pointerLockElement===renderer.domElement)mouseDown=true}});document.addEventListener('mouseup',()=>mouseDown=false);renderer.domElement.addEventListener('click',()=>{if(started&&alive&&!paused&&matchMedia('(pointer:fine)').matches&&document.pointerLockElement!==renderer.domElement)renderer.domElement.requestPointerLock?.()});
+function reload(){if(!started||reloadTimer>0||ammo===30||reserve<=0)return;reloadTimer=1.25;showToast('RELOADING')}
+$('#reloadbtn').addEventListener('pointerdown',e=>{e.preventDefault();reload()});$('#firebtn').addEventListener('pointerdown',e=>{e.preventDefault();mouseDown=true});['pointerup','pointercancel','pointerleave'].forEach(ev=>$('#firebtn').addEventListener(ev,()=>mouseDown=false));
+const stickEl=$('#stick');stickEl.addEventListener('pointerdown',e=>{stickEl.setPointerCapture(e.pointerId);mobileLook='move'});stickEl.addEventListener('pointermove',e=>{if(mobileLook==='move'){const r=stickEl.getBoundingClientRect();stickVector.x=THREE.MathUtils.clamp((e.clientX-r.left-r.width/2)/38,-1,1);stickVector.y=THREE.MathUtils.clamp((e.clientY-r.top-r.height/2)/38,-1,1)}});['pointerup','pointercancel'].forEach(ev=>stickEl.addEventListener(ev,()=>{mobileLook=null;stickVector={x:0,y:0}}));
